function toIndex(){goToURL("/WeixinService/activity/nationalDayActivity/nationalDayStart.shtml")}function next(n){$("#flagShow").val("0");index=index+1;activityStatisticalLog("0"+index);$("#"+n).hide().next().show()}function comit(){var t,i,r;if(index=10,activityStatisticalLog(index),t=$("ul li.act").length,t==null||t!=5){errorRemark("还有未做题目");return}var n="";for(i=0;i<t;i++)r=$("ul li.act").eq(i).attr("data-score"),n=n!=""?n+","+r:n+r;$.ajax({async:!0,url:"/WeixinService/activity/nationalDayQA.xhtml",data:{answer:n},dataType:"json",cache:!1,type:"post",error:function(){},success:function(n){$("#flagShow").val("1");$("#scoreNum").val(n.answer);$("#section_05").hide();$("#successQA").show();$(".score-value em").html(n.answer);n.answer>=0&&n.answer<=40?$("#resultAnswer").html("赶紧自觉加强爱国主义教育!"):n.answer>40&&n.answer<=60?$("#resultAnswer").html("还不错,合格的爱国主义好青年!"):n.answer>60&&n.answer<=80?$("#resultAnswer").html("绝对社会主义好青年!"):n.answer>80&&n.answer<=100?$("#resultAnswer").html("太完美了,发给朋友震撼一下他们吧!"):$("#resultAnswer").html("赶紧自觉加强爱国主义教育!");share()}})}function shareShow(n){activityStatisticalLog("11");n?$("#shadow").show():$("#shadow").hide()}var index=2;$(document).ready(function(){$("#flagShow").val("0");document.title="迎接祖国67岁生日";activityStatisticalLog("02")});$("section ul li").click(function(){$(this).siblings().removeClass("act");$(this).addClass("act");$(this).parents(".title").attr("id")=="section_05"||window.setTimeout('next("'+$(this).parents(".title").attr("id")+'")',500)});$("section div a.pre_question").click(function(){index=index-1;activityStatisticalLog("0"+index);$(this).parents(".title").hide().prev().show()})